const __pageData = JSON.parse('{"title":"Session Persistence","description":"","frontmatter":{"editSource":"docs/subsystems/persistence.md","outline":[2,3]},"headers":[],"relativePath":"en/reference/subsystems/persistence.md","filePath":"en/reference/subsystems/persistence.md"}');
